{
  "name": "opencode-token-speed-plugin-built",
  "version": "1.0.5",
  "description": "OpenCode TUI plugin: live tokens/sec readout. Forked build of opencode-token-speed-plugin (upstream v1.0.4 shipped raw .tsx with no build step; this publishes the compiled dist that actually loads).",
  "type": "module",
  "main": "dist/tui.js",
  "exports": {
    ".": {
      "import": "./dist/tui.js",
      "types": "./types.d.ts"
    },
    "./tui": {
      "import": "./dist/tui.js",
      "types": "./types.d.ts"
    }
  },
  "files": [
    "dist/tui.js",
    "types.d.ts",
    "README.md",
    "LICENSE"
  ],
  "keywords": [
    "opencode",
    "opencode-plugin",
    "token-speed",
    "tui"
  ],
  "author": "heimoshuiyu (original); fork build by hardes11",
  "license": "MIT",
  "dependencies": {
    "@opencode-ai/plugin": "*",
    "@opentui/solid": "0.1.107",
    "solid-js": "1.9.10"
  },
  "repository": {
    "type": "git",
    "url": "https://github.com/hardes11/opencode-token-speed-plugin.git"
  },
  "homepage": "https://github.com/hardes11/opencode-token-speed-plugin#readme"
}
